package com.EOT.project.controller;
import com.EOT.project.dto.request.PostRequestDTO; import com.EOT.project.dto.response.PostResponseDTO; import com.EOT.project.service.*; import java.util.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class PostControllerTest { @Mock PostService service; @Mock CurrentUserService current; @InjectMocks PostController controller;
 @Test void createsOnlyAfterOwnershipCheck() { UUID userId=UUID.randomUUID(); var dto=PostRequestDTO.builder().threadId(UUID.randomUUID()).userId(userId).content("x").build(); when(service.create(dto)).thenReturn(PostResponseDTO.builder().build()); var auth=new UsernamePasswordAuthenticationToken("auth","x"); assertThat(controller.createPost(dto,auth).getStatusCode().value()).isEqualTo(201); verify(current).requireOwnerOrAdmin(auth,userId); } }
